css:
:root{
  --forest:#12401f;--green-700:#1b7a3e;--green:#2f9e44;--green-lt:#51cf66;--lime:#a9e34b;
  --amber:#f59f00;--amber-d:#e08a00;--ink:#11291a;--body:#465a4e;--muted:#7a8c80;
  --bg:#f2faf4;--card:#fff;--line:#dcefe1;--mint:#eafaef;
  --ring:rgba(47,158,68,.3);--shadow:0 16px 44px rgba(18,64,31,.14);--shadow-sm:0 4px 16px rgba(18,64,31,.08);--radius:16px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:'Inter',-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:var(--body);background:var(--bg);line-height:1.65;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:'Poppins',sans-serif;color:var(--ink);line-height:1.12;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.9rem,3.8vw,2.7rem)}
h3{font-size:1.25rem;font-weight:700}
p{margin:0 0 1rem}
.ic{width:1.25em;height:1.25em;display:inline-block;vertical-align:-.28em;flex:none}
.wrap{max-width:1180px;margin:0 auto;padding:0 24px}
.section{padding:76px 0}
.eyebrow{display:inline-block;font-family:'Poppins',sans-serif;font-size:.78rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--green-700);background:var(--mint);padding:7px 14px;border-radius:999px;margin-bottom:16px}
.lead{font-size:1.14rem;color:var(--body);max-width:64ch}
.center{text-align:center}.center .lead{margin:0 auto}
.btn{display:inline-flex;align-items:center;gap:.55rem;font-family:'Poppins',sans-serif;font-weight:700;font-size:.98rem;padding:13px 24px;border-radius:12px;border:2px solid transparent;cursor:pointer;transition:transform .12s,box-shadow .12s,background .12s,color .12s;white-space:nowrap}
.btn:active{transform:translateY(1px)}
.btn-amber{background:var(--amber);color:#3a2600;box-shadow:0 10px 22px rgba(245,159,0,.32)}
.btn-amber:hover{background:var(--amber-d)}
.btn-green{background:var(--green);color:#fff;box-shadow:0 10px 22px rgba(47,158,68,.28)}
.btn-green:hover{background:var(--green-700)}
.btn-outline{background:#fff;color:var(--green-700);border-color:#cfead6}
.btn-outline:hover{border-color:var(--green);background:var(--mint)}
.btn-lightline{background:transparent;color:#fff;border-color:rgba(255,255,255,.5)}
.btn-lightline:hover{background:rgba(255,255,255,.14)}
.btn-block{width:100%;justify-content:center}
.brand{display:flex;align-items:center;gap:12px;flex:0 0 auto}
.brand .emb{width:52px;height:52px;flex:none}
.wm,.wm-d{display:flex;flex-direction:column;line-height:1}
.wm b,.wm-d b{font-family:'Poppins',sans-serif;font-weight:800;font-size:1.32rem;color:var(--green-700);letter-spacing:-.01em}
.wm small,.wm-d small{font-family:'Poppins',sans-serif;font-weight:600;font-size:.66rem;letter-spacing:.34em;color:var(--amber);margin-top:3px}
.wm-d b{color:#fff}.wm-d small{color:var(--lime)}
.util{background:var(--forest);color:rgba(255,255,255,.86);font-size:.85rem}
.util .wrap{display:flex;align-items:center;justify-content:space-between;min-height:42px;gap:16px}
.util a{color:rgba(255,255,255,.9);font-weight:600;display:inline-flex;align-items:center;gap:6px}
.util a:hover{color:var(--lime)}.util .l,.util .r{display:flex;gap:20px;align-items:center;flex-wrap:wrap}
.util .ic{color:var(--lime)}
@media(max-width:720px){.util .l span{display:none}}
header.site{position:sticky;top:0;z-index:60;background:rgba(255,255,255,.94);backdrop-filter:saturate(150%) blur(10px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;gap:18px;min-height:84px}
.nav-links{display:flex;gap:26px;align-items:center;flex:1 1 auto;justify-content:center}
.nav-links>a,.drop-toggle{font-family:'Poppins',sans-serif;font-weight:600;color:var(--ink);font-size:.96rem;background:none;border:0;cursor:pointer;display:inline-flex;align-items:center;gap:5px;padding:8px 0}
.nav-links>a:hover,.drop-toggle:hover,.has-drop.active>.drop-toggle,.nav-links>a.on{color:var(--green)}
.caret{width:.85em;height:.85em;transition:transform .15s}
.has-drop{position:relative}
.dropdown{position:absolute;top:100%;left:50%;transform:translateX(-50%) translateY(10px);min-width:300px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:10px;display:grid;grid-template-columns:1fr 1fr;gap:2px;opacity:0;visibility:hidden;transition:.15s;z-index:70}
.has-drop:hover .dropdown,.has-drop:focus-within .dropdown,.has-drop.open .dropdown{opacity:1;visibility:visible;transform:translateX(-50%) translateY(4px)}
.has-drop:hover .caret,.has-drop.open .caret{transform:rotate(180deg)}
.dropdown a{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:9px;font-weight:600;color:var(--ink);font-size:.9rem}
.dropdown a:hover{background:var(--mint);color:var(--green-700)}
.dropdown a .ic{color:var(--green)}
.nav-cta{display:flex;align-items:center;gap:10px;flex:0 0 auto}
.nav-toggle{display:none;width:44px;height:44px;border-radius:10px;border:1px solid var(--line);background:#fff;cursor:pointer;place-items:center;color:var(--ink)}
@media(max-width:1120px){.nav-cta .callbtn{display:none}}
@media(max-width:980px){
  .nav-links{display:none;position:absolute;top:100%;left:0;right:0;background:#fff;border-bottom:1px solid var(--line);flex-direction:column;align-items:stretch;gap:0;padding:10px 24px 16px;box-shadow:var(--shadow)}
  header.site.nav-open .nav-links{display:flex}
  .nav-links>a,.drop-toggle{padding:13px 4px;border-bottom:1px solid var(--line);width:100%;justify-content:space-between}
  .has-drop{position:static}.dropdown{position:static;transform:none;opacity:1;visibility:visible;box-shadow:none;border:0;grid-template-columns:1fr;padding:4px 0 8px 8px;min-width:0}
  .nav-toggle{display:grid}.brand{flex:1 1 auto}
}
.hills{position:absolute;left:0;right:0;bottom:-1px;width:100%;height:auto;z-index:1;display:block}
/* generic photo CTA banner */
.banner{position:relative;border-radius:24px;overflow:hidden;background-size:cover;background-position:center;min-height:320px;display:flex;align-items:center}
.banner::before{content:"";position:absolute;inset:0;background:linear-gradient(100deg,rgba(15,54,26,.92),rgba(20,83,42,.62) 70%,rgba(27,122,62,.35))}
.banner .bc{position:relative;z-index:1;padding:44px;color:#fff;max-width:640px}
.banner .bc h2{color:#fff}.banner .bc p{color:rgba(255,255,255,.9)}
.banner .bc .row{display:flex;gap:12px;flex-wrap:wrap;margin-top:6px}
/* generic closing CTA band */
.ctaband{background:linear-gradient(120deg,var(--forest),var(--green-700) 60%,var(--green));color:#fff;border-radius:24px;padding:54px;text-align:center;position:relative;overflow:hidden}
.ctaband::after{content:"";position:absolute;width:440px;height:440px;border-radius:50%;background:radial-gradient(circle,rgba(245,159,0,.22),transparent 62%);top:-150px;left:-100px}
.ctaband h2{color:#fff;position:relative}
.ctaband p{color:rgba(255,255,255,.9);max-width:56ch;margin:0 auto 22px;position:relative}
.ctaband .row{display:flex;gap:14px;flex-wrap:wrap;justify-content:center;position:relative}
.ctaband .phone{font-family:'Poppins',sans-serif;font-weight:800;font-size:1.6rem;color:#fff;margin-top:14px;display:inline-block;position:relative}
/* footer */
footer.site{background:var(--forest);color:rgba(255,255,255,.72);padding:60px 0 28px}
footer.site a:hover{color:var(--lime)}
.foot-top{display:grid;grid-template-columns:1.6fr 1fr 1fr 1.2fr;gap:30px}
@media(max-width:860px){.foot-top{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.foot-top{grid-template-columns:1fr}}
footer.site h4{font-family:'Poppins',sans-serif;color:#fff;font-size:.86rem;letter-spacing:.08em;text-transform:uppercase;margin:0 0 14px}
footer.site ul{list-style:none;margin:0;padding:0}footer.site li{margin-bottom:9px;font-size:.92rem}
.foot-brand p{font-size:.92rem;color:rgba(255,255,255,.62);max-width:34ch;margin-top:14px}
.foot-contact li{display:flex;gap:9px;align-items:flex-start}.foot-contact .ic{color:var(--lime);flex:none;margin-top:2px}
.foot-bottom{border-top:1px solid rgba(255,255,255,.14);margin-top:34px;padding-top:20px;font-size:.82rem;color:rgba(255,255,255,.55);display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}
.callbar{display:none;position:fixed;left:0;right:0;bottom:0;z-index:80;background:#fff;border-top:1px solid var(--line);box-shadow:0 -6px 20px rgba(18,64,31,.12);padding:9px 12px;gap:10px}
.callbar a{flex:1;justify-content:center;padding:12px}
@media(max-width:720px){.callbar{display:flex}body{padding-bottom:74px}}
/* generic inner-page hero (solid brand gradient; page types may override) */
.phero{position:relative;background:linear-gradient(160deg,var(--forest),var(--green-700) 70%,var(--green));color:#fff;overflow:hidden}
.phero .wrap{position:relative;z-index:2;padding:64px 24px 84px}
.phero .eyebrow{color:#fff;background:rgba(255,255,255,.14)}
.phero h1{color:#fff;font-size:clamp(2.2rem,4.8vw,3.4rem);margin-bottom:.25em;max-width:20ch}
.phero p{color:rgba(255,255,255,.92);font-size:1.16rem;max-width:60ch;margin:0}
.crumb{font-size:.86rem;color:rgba(255,255,255,.75);margin-bottom:14px;position:relative;z-index:2}
.crumb a{color:rgba(255,255,255,.85)}.crumb a:hover{color:var(--lime)}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

.field{margin-bottom:12px}
.field label{display:block;font-size:.82rem;font-weight:700;color:var(--ink);margin-bottom:5px}
.field input,.field select,.field textarea{width:100%;padding:12px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:.95rem;color:var(--ink);background:#fbfefc}
.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--green);box-shadow:0 0 0 4px var(--ring)}
.field textarea{min-height:90px;resize:vertical}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:12px}
@media(max-width:520px){.grid-2{grid-template-columns:1fr}}
.reassure{display:flex;align-items:center;gap:8px;justify-content:center;color:var(--muted);font-size:.82rem;font-weight:600;margin-top:12px}
details{background:#fff;border:1px solid var(--line);border-radius:12px;margin-bottom:12px;box-shadow:var(--shadow-sm);overflow:hidden}
details[open]{border-color:var(--green-lt)}
summary{cursor:pointer;list-style:none;padding:16px 50px 16px 20px;font-family:'Poppins',sans-serif;font-weight:600;color:var(--ink);position:relative;font-size:1rem}
summary::-webkit-details-marker{display:none}
summary::after{content:"+";position:absolute;right:20px;top:50%;transform:translateY(-50%);font-size:1.4rem;color:var(--green)}
details[open] summary::after{content:"\2013"}
.faq-a{padding:0 20px 18px;color:var(--body);font-size:.95rem}

/* location hero: LIGHT split with map card — deliberately unlike the dark service-page hero */
.lo-hero{background:linear-gradient(180deg,var(--mint),#fff);border-bottom:1px solid var(--line);position:relative;overflow:hidden}
.lo-hero .wrap{padding:44px 24px 52px}
.lo-crumb{font-size:.85rem;color:var(--muted);margin-bottom:16px}
.lo-crumb a{color:var(--green-700)}.lo-crumb a:hover{text-decoration:underline}
.lo-split{display:grid;grid-template-columns:1.25fr .85fr;gap:40px;align-items:center}
@media(max-width:880px){.lo-split{grid-template-columns:1fr;gap:26px}}
.lo-tag{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--line);color:var(--green-700);font-family:'Poppins',sans-serif;font-weight:700;font-size:.82rem;padding:7px 14px;border-radius:999px;margin-bottom:14px}
.lo-tag .ic{color:var(--amber);width:1.05em;height:1.05em}
.lo-hero h1{font-size:clamp(2.1rem,4.6vw,3.1rem);margin-bottom:.25em}
.lo-hero h1 span{color:var(--green)}
.lo-hero p{font-size:1.08rem;max-width:56ch;margin:0 0 20px}
.lo-hero .hbtns{display:flex;gap:12px;flex-wrap:wrap}
.mapcard{background:linear-gradient(155deg,var(--green-700),var(--forest));border-radius:22px;padding:30px;color:#fff;position:relative;overflow:hidden;box-shadow:var(--shadow)}
.mapcard::after{content:"";position:absolute;width:260px;height:260px;border-radius:50%;background:radial-gradient(circle,rgba(169,227,75,.22),transparent 62%);bottom:-90px;right:-70px}
.mapcard .pin{width:58px;height:58px;border-radius:50%;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.28);display:grid;place-items:center;margin-bottom:14px;position:relative}
.mapcard .pin .ic{width:28px;height:28px;color:var(--lime)}
.mapcard h3{color:#fff;font-size:1.3rem;margin:0 0 4px;position:relative}
.mapcard .sub{color:rgba(255,255,255,.82);font-size:.92rem;margin-bottom:16px;position:relative}
.mapcard ul{list-style:none;padding:0;margin:0;display:grid;gap:10px;position:relative}
.mapcard li{display:flex;gap:9px;align-items:center;font-size:.95rem;font-weight:600}
.mapcard li .ic{color:var(--lime);flex:none}
.mapcard a{color:#fff}

/* local intro band */
.lo-intro{max-width:820px}
.lo-intro p{font-size:1.06rem}

/* services offered: compact tile grid (distinct from service page's big rows) */
.lo-svc{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
@media(max-width:900px){.lo-svc{grid-template-columns:1fr 1fr}}
@media(max-width:480px){.lo-svc{grid-template-columns:1fr}}
.lo-svc a{display:flex;align-items:center;gap:12px;background:#fff;border:1px solid var(--line);border-radius:12px;padding:15px 16px;font-family:'Poppins',sans-serif;font-weight:600;font-size:.95rem;color:var(--ink);box-shadow:var(--shadow-sm);transition:.15s}
.lo-svc a:hover{border-color:var(--green);color:var(--green-700);transform:translateY(-3px)}
.lo-svc a .si{width:40px;height:40px;border-radius:10px;background:var(--mint);color:var(--green-700);display:grid;place-items:center;flex:none}
.lo-svc a .si .ic{width:22px;height:22px}

/* why-local: text + checklist on forest */
.lo-why{background:var(--forest);color:#fff;border-radius:24px;padding:48px;position:relative;overflow:hidden}
.lo-why::after{content:"";position:absolute;width:400px;height:400px;border-radius:50%;background:radial-gradient(circle,rgba(169,227,75,.14),transparent 62%);top:-150px;right:-110px}
.lo-why h2{color:#fff;position:relative}
.lo-why p{color:rgba(255,255,255,.86);position:relative;max-width:60ch}
.lo-why .wl{list-style:none;padding:0;margin:18px 0 0;display:grid;grid-template-columns:1fr 1fr;gap:12px;position:relative}
@media(max-width:640px){.lo-why .wl{grid-template-columns:1fr}}
.lo-why .wl li{display:flex;gap:10px;align-items:flex-start;font-weight:600;font-size:.96rem}
.lo-why .wl .ic{color:var(--lime);flex:none;margin-top:2px}

/* nearby chips */
.nearby{display:flex;flex-wrap:wrap;gap:9px;margin-top:14px}
.nearby a{display:inline-flex;align-items:center;gap:7px;background:#fff;border:1px solid var(--line);border-radius:999px;padding:8px 15px;font-weight:600;font-size:.9rem;color:var(--ink)}
.nearby a:hover{border-color:var(--green);color:var(--green-700);background:var(--mint)}
.nearby a .ic{color:var(--green);width:1em;height:1em}

/* bottom form split */
.lo-form{display:grid;grid-template-columns:1fr 1.05fr;gap:40px;align-items:start}
@media(max-width:880px){.lo-form{grid-template-columns:1fr;gap:28px}}
.lo-form .fcard{background:#fff;border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);padding:30px}
.lo-form .fcard h2{font-size:1.5rem;margin-bottom:2px}
.lo-form .fcard .qsub{color:var(--muted);font-size:.95rem;margin-bottom:16px}
.fq2{max-width:none}
